import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import api from '../api/axios';
import { Container, Table, Button, Alert, Spinner, Form, Modal } from 'react-bootstrap';

const Students = () => {
  const [students, setStudents] = useState([]);
  const [classes, setClasses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [newClassId, setNewClassId] = useState('');
  const roles = useSelector(state => state.auth.roles || []);

  useEffect(() => {
    fetchStudents();
    fetchClasses();
  }, []);

  const fetchStudents = async () => {
    setLoading(true);
    try {
      const res = await api.get('/director/students');
      setStudents(res.data);
    } catch (err) {
      setError(err.response?.data?.error || 'Ошибка загрузки учеников');
    } finally {
      setLoading(false);
    }
  };

  const fetchClasses = async () => {
    try {
      const res = await api.get('/director/classes');
      setClasses(res.data);
    } catch (err) {
      console.error('Ошибка загрузки классов:', err);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Удалить ученика?')) {
      try {
        await api.delete(`/director/student/${id}`);
        setStudents(students.filter(s => s.id !== id));
      } catch (err) {
        alert('Ошибка удаления');
      }
    }
  };

  const handleOpenChangeClass = (student) => {
    setSelectedStudent(student);
    setNewClassId(student.class_id || '');
    setShowModal(true);
  };

  const handleChangeClass = async () => {
    try {
      await api.put('/director/student/class', {
        studentId: selectedStudent.id,
        classId: newClassId || null
      });
      setShowModal(false);
      fetchStudents(); // Обновляем список
      alert('Класс успешно изменён!');
    } catch (err) {
      alert('Ошибка изменения класса: ' + (err.response?.data?.message || ''));
    }
  };

  const isDirector = roles.includes('Директор');

  if (loading) {
    return (
      <Container className="text-center mt-5">
        <Spinner animation="border" variant="primary" />
        <p>Загрузка...</p>
      </Container>
    );
  }

  return (
    <Container className="mt-4">
      <h3>Ученики</h3>
      {error && <Alert variant="danger">{error}</Alert>}
      
      <Table striped bordered hover responsive>
        <thead>
          <tr>
            <th>ФИО</th>
            <th>Логин</th>
            {isDirector && <th>Пароль</th>}
            <th>Класс</th>
            <th>Email</th>
            <th>Средняя оценка</th>
            {isDirector && <th>Действия</th>}
          </tr>
        </thead>
        <tbody>
          {students.length === 0 ? (
            <tr>
              <td colSpan={isDirector ? 7 : 5} className="text-center">
                Нет учеников
              </td>
            </tr>
          ) : (
            students.map(s => (
              <tr key={s.id}>
                <td>{s.last_name} {s.first_name} {s.middle_name}</td>
                <td><code>{s.login}</code></td>
                {isDirector && (
                  <td>
                    <code style={{ 
                      backgroundColor: '#f0f0f0', 
                      padding: '2px 6px', 
                      borderRadius: '4px',
                      cursor: 'pointer'
                    }}
                    onClick={() => {
                      navigator.clipboard?.writeText(s.plain_password || '');
                      alert('Пароль скопирован в буфер обмена!');
                    }}
                    title="Нажмите, чтобы скопировать пароль"
                    >
                      {s.plain_password || '—'}
                    </code>
                  </td>
                )}
                <td>
                  <Button 
                    variant="outline-secondary" 
                    size="sm"
                    onClick={() => handleOpenChangeClass(s)}
                    title="Изменить класс"
                  >
                    {s.class_name || 'Не назначен'} ✏️
                  </Button>
                </td>
                <td>{s.email}</td>
                <td>
                  <strong style={{ 
                    color: s.average_grade >= 4 ? 'green' : 
                           s.average_grade >= 3 ? 'orange' : 'red' 
                  }}>
                    {s.average_grade}
                  </strong>
                </td>
                {isDirector && (
                  <td>
                    <Button variant="danger" size="sm" onClick={() => handleDelete(s.id)}>
                      Удалить
                    </Button>
                  </td>
                )}
              </tr>
            ))
          )}
        </tbody>
      </Table>
      
      {/* Модальное окно изменения класса */}
      <Modal show={showModal} onHide={() => setShowModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Изменить класс ученика</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <p><strong>Ученик:</strong> {selectedStudent?.last_name} {selectedStudent?.first_name}</p>
          <Form.Group>
            <Form.Label>Выберите класс</Form.Label>
            <Form.Select
              value={newClassId}
              onChange={(e) => setNewClassId(e.target.value)}
            >
              <option value="">Не назначен</option>
              {classes.map(cls => (
                <option key={cls.id} value={cls.id}>
                  {cls.grade} класс
                </option>
              ))}
            </Form.Select>
          </Form.Group>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Отмена
          </Button>
          <Button variant="primary" onClick={handleChangeClass}>
            Сохранить
          </Button>
        </Modal.Footer>
      </Modal>
      
      {isDirector && (
        <div className="mt-2 text-muted small">
          <p>💡 Нажмите на <strong>класс</strong> ученика, чтобы изменить его. Пароль отображается только для директора.</p>
        </div>
      )}
    </Container>
  );
};

export default Students;
